'Enable_Pos_Salesperson_Switch_Hint' => 'Tizimdan chiqmasdan sotuvni boshqa xodimga biriktirish uchun POS ekranida sotuvchi tanlagichini koʻrsatish. Tanlangan sotuvchi hisob-fakturada saqlanadi va sotuv hisobotlarida ishlatiladi; faol POS seansi oʻzgarmaydi.',
'Wallet_Payment_Method_Missing' => 'Wallet toʻlov usuli mavjud emas',
'Wallet_Payment_Method_Missing_Help' => 'Aynan "Wallet" nomli toʻlov usuli topilmadi. POS dagi hamyon toʻlovi shu nom boʻyicha aniqlanadi, shuning uchun bu yerda "Wallet" nomli toʻlov usulini qoʻshmaguningizcha mijozlar hamyoni bilan toʻlay olmaydi:',
'Show_Previous_Dues_Line' => 'Oldingi qarzlar qatorini koʻrsatish',
'Show_Previous_Dues_Line_Desc' => 'Mijozning ushbu sotuvdan oldingi qarzi. Faqat noldan katta boʻlganda chop etiladi.',
'Show_Net_Balance_Line' => 'Sof balans qatorini koʻrsatish',
