'QZ_Tray_Printer' => 'QZ Tray (ushbu kompyuterdagi printer)',
'QZ_Printer_Name_Hint' => 'QZ Tray ishlayotgan kompyuterda koʻrinadigan printer nomi. Oʻsha kompyuterning standart printeridan foydalanish uchun boʻsh qoldiring. Printerlarni aniqlash uchun ⟳ tugmasini bosing.',
'QZ_Not_Running' => 'Bu kompyuterda QZ Tray ishlamayapti. Uni qz.io saytidan oʻrnating va ishlab turgan holda qoldiring, soʻng QZ soʻraganda ushbu veb-saytga ruxsat bering.',
'Detect_Printers' => 'Printerlarni aniqlash',
'QZ_Download_Cert' => 'Sertifikatni yuklab olish (override.crt)',
'QZ_Setup_Title' => 'QZ Tray orqali chop etishni qanday sozlash kerak (yorliq chop etadigan har bir kompyuterda bir marta)',
'QZ_Step_Install' => '1. Ushbu kompyuterga QZ Tray ni oʻrnating — uni qz.io saytidan bepul yuklab oling, soʻng ishga tushiring va ishlab turgan holda qoldiring (Windows da tizim tepsisida, macOS da menyu satrida joylashadi).',
'QZ_Step_Connect' => '2. Yorliq printeringizni USB orqali ulang va u operatsion tizimda oʻrnatilganini tekshiring (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Ushbu kompyuterdagi printerlarni aniqlash uchun yuqoridagi "Printer nomi" yonidagi ⟳ tugmasini bosing, soʻng yorliq printeringizni tanlang. Kompyuterning standart printeridan foydalanish uchun maydonni boʻsh qoldiring.',
'QZ_Step_Cert' => '4. Ruxsat soʻrovisiz chop etish uchun quyidagi sertifikatni yuklab oling va uni override.crt deb qayta nomlab, QZ Tray oʻrnatish papkasiga nusxalang (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Soʻng QZ Tray dan chiqing va uni qayta ishga tushiring.',
'QZ_Step_Test' => '5. Quyidagi "Sinov yorligʻini chop etish" tugmasini bosing. Agar QZ Tray ruxsat soʻrasa, Allow tugmasini bosing — sertifikat oʻrnatilgan boʻlsa, u qayta soʻramaydi.',
'QZ_Step_Save' => '6. Ushbu sozlamalarni saqlash uchun Yuborish tugmasini bosing. Endi Shtrix-kodni chop etish sahifasidagi yorliqlar brauzerning chop etish oynasisiz toʻgʻridan-toʻgʻri ushbu printerda chop etiladi.',
'QZ_Setup_Note' => 'QZ Tray siz ishlayotgan kompyuterda ishlaydi, shuning uchun bu Stocky masofaviy serverda joylashgan boʻlsa ham ishlaydi. Yorliq chop etadigan har bir kompyuterda QZ Tray oʻrnatilgan boʻlishi kerak.',
'PWA_Enabled' => 'Oʻrnatiladigan ilovani yoqish',
'PWA_Enabled_Help' => 'Brauzerlarga ushbu ilovani telefon, planshet va kompyuterlarga oʻrnatishni taklif qilish imkonini beradi va oflayn sahifalarni keshda saqlaydi. Buni oʻchirish oʻrnatish taklifini hamma joydan olib tashlaydi va keyingi tashrifda keshni tozalaydi.',
