'PWA_Launch' => 'Ishga tushirish va koʻrinish',
'PWA_App_Name' => 'Ilova nomi',
'PWA_App_Name_Help' => 'Oʻrnatish taklifida va ilovalar roʻyxatida koʻrsatiladi. Koʻrinish sozlamalaridagi ilova nomidan foydalanish uchun boʻsh qoldiring.',
'PWA_Short_Name' => 'Qisqa nom',
