'Label_Render_Mode' => 'Yorliqni chizish',
'Label_Render_Mode_Hint' => 'Yorliq qanday chiziladi. Printer shriftlari eng tez va eng aniq shtrix-kod beradi, lekin faqat asosiy lotin belgilarini printerning oʻz shriftida chop etadi. Koʻrinish rasmi yorliq dizayningizni aynan takrorlaydi — siz tanlagan shrift, istalgan til — xuddi maxsus yorliq dasturlari kabi.',
