'Label_Size_Hint' => 'Rulondagi bitta stikerning jismoniy oʻlchami. U yuklangan yorliqlarga aynan mos kelishi kerak — notoʻgʻri oʻlcham printerni boʻshliqni notoʻgʻri joydan qidirishga majbur qiladi va har bir yorliq tobora siljib chop etiladi.',
