'Find_Resolution' => 'Aniqlikni topish',
'Find_Resolution_Hint' => '203 va 300 deb belgilangan ikkita yorliq chop etiladi. Toʻgʻrisida stikerda toʻrt tomonida kichik teng chekka bilan toʻliq toʻrtburchak koʻrinadi; notoʻgʻrisida chegaralar yetishmaydi yoki keyingi stikerga oʻtib ketadi.',
'Dpi_Test_Sent' => '203 va 300 deb belgilangan ikkita yorliq chop etilmoqda. Toʻgʻrisida toʻrt tomonida kichik, teng chekka bilan toʻliq toʻrtburchak koʻrinadi — "Chop etish kallagi aniqligi" ni shu raqamga oʻrnating va saqlang.',
'Label_Offset_X' => 'Gorizontal siljish (mm)',
