'Label_Offset_Y' => 'Vertikal siljish (mm)',
'Label_Offset_Y_Hint' => 'Chop etishni yorliq boʻylab siljitadi. Dizaynning yuqori qismi kesilgan yoki yoʻq boʻlsa, oshiring; juda pastdan boshlansa, kamaytiring.',
