'Enable_Wholesale_Pricing_Hint' => 'Mahsulotlarga miqdor pogʻonalarini (10-19 dona, 20-49 dona, 100+ ...) belgilash imkonini beradi; buyurtma miqdori pogʻonaga yetganda ular POS va onlayn doʻkonda chakana narxni avtomatik almashtiradi. Oʻchirilsa, hamma narsa yana oddiy chakana narxda sotiladi — sozlangan pogʻonalar saqlanadi, faqat qoʻllanilmaydi.',
