'Ord_Guide_Payment_Title' => 'Toʻlov holati',
'Ord_Guide_Payment_Intro' => 'Bu ustun mijoz rasmiylashtirishda qanday toʻlashni tanlaganini qayd etadi. U onlayn doʻkon tomonidan belgilanadi va bu sahifadan tahrirlab boʻlmaydi — pulning oʻzi buyurtmani tasdiqlash natijasida yaratilgan sotuvda kuzatiladi.',
'Ord_Guide_Payment_Paid' => 'Mijoz allaqachon toʻlov shlyuzi orqali onlayn toʻlagan. Buyurtmani tasdiqlash sotuvni Toʻlangan sifatida yaratadi va toʻlovni siz uchun qayd etadi — boshqa hech narsa qilish shart emas.',
'Ord_Guide_Payment_Pending' => 'Yetkazib berishda naqd toʻlov, bank oʻtkazmasi yoki boshqa keyinroq toʻlash usuli. Buyurtmani tasdiqlash sotuvni Toʻlanmagan sifatida yaratadi, shuning uchun pulni olganingizdan keyin oʻzingiz qayd etasiz — quyidagi qadamlarga qarang.',
'Ord_Guide_Payment_Failed' => 'Toʻlov shlyuzi toʻlovni rad etdi yoki mijoz uni tashlab ketdi. Buyurtma avtomatik bekor qilinadi.',
'Ord_Guide_MarkPaid_Title' => 'Toʻlovni kutilayotgandan toʻlanganga oʻzgartirish',
'Ord_Guide_MarkPaid_Step1' => 'Avval buyurtmani shu yerda tasdiqlang — sotuvni aynan tasdiqlash yaratadi.',
'Ord_Guide_MarkPaid_Step2' => 'Sotuvlar > Barcha sotuvlar ni oching va oʻsha sotuvni toping (xuddi shu mijoz, tafsilotlar sahifasida u qaysi onlayn buyurtmadan kelgani koʻrsatiladi).',
'Ord_Guide_MarkPaid_Step3' => 'Qator amallari menyusini oching va Toʻlov yaratish ni tanlang.',
'Ord_Guide_MarkPaid_Step4' => 'Summa, toʻlov usuli va sanani kiriting, soʻng saqlang. Sotuv summaga qarab oʻz-oʻzidan Qisman yoki Toʻlangan holatiga oʻtadi.',
'Ord_Guide_MarkPaid_Note' => 'Bu yerda koʻrsatilgan Toʻlov holati rasmiylashtirishdagi tanlovni qayd etishda davom etadi va oʻzgarmaydi. Sotuv buxgalteriya yozuvidir va aynan u toʻlov va foyda hisobotlaringizni toʻldiradi. Kiritgan maʼlumotlaringizni koʻrib chiqish yoki tahrirlash uchun sotuvdagi Toʻlovlarni koʻrsatish dan foydalaning.',
'Ord_Guide_Notes_Title' => 'Bilish foydali',
'Ord_Guide_Note_Warehouse' => 'Tasdiqlashda tanlagan omboringiz zaxira qayerdan olinishini belgilaydi. Butun buyurtmani qoplay olmaydigan omborlar oʻsha roʻyxatda Mavjud emas deb belgilanadi.',
'Ord_Guide_Note_Preorder' => 'Oldindan buyurtma mahsulotlari zaxira tekshiruvidan oʻtkazib yuboriladi, shuning uchun ularni oʻz ichiga olgan buyurtma miqdor hali mavjud boʻlmasa ham tasdiqlanishi mumkin.',
'Ord_Guide_Note_Flagged' => 'Belgilangan tegi buyurtma rasmiylashtirishda firibgarlik tekshiruviga tushganini bildiradi. Sababni koʻrish uchun kursorni teg ustiga olib boring va tasdiqlashdan oldin buyurtmani koʻrib chiqing.',
'Ord_Guide_Note_Cancel' => 'Bekor qilish faqat buyurtma hali kutilayotgan holatda boʻlganda mumkin. Tasdiqlangandan keyin uni sotuv yoki mijoz qaytarishi orqali bekor qiling.',
