'VG_Opt_Step2' => 'Rang yoki Oʻlcham kabi parametr nomini yozing yoki takliflardan birini tanlang.',
'VG_Opt_Step3' => 'Qiymatni yozing (masalan, Qizil) va Enter tugmasini bosing. Har bir qiymat uchun takrorlang; vergul ham qiymatlarni ajratadi. Qiymatni olib tashlash uchun undagi x belgisini bosing.',
