'VG_Opt_Step5' => '"Variantlarni yaratish" tugmasini bosing. Har bir kombinatsiya uchun bitta qator yaratiladi va uning nomi avtomatik tuziladi, masalan, "Qizil / S".',
'VG_Opt_Step6' => 'Har bir qatorga tannarx va narxni kiriting yoki "Hammasiga qoʻllash" maydoniga qiymat yozib, uni har bir qatorga nusxalash uchun Tannarx yoki Narx tugmasini bosing.',
