'VG_Rows_Title' => 'Variant qatorlari',
'VG_Rows_Text' => 'Har bir qatorda rasm, kod, shtrix-kod, tannarx, narx, ulgurji narx va minimal sotish narxi bor. Mahsulot yaratishda har bir variant uchun omborlar boʻyicha boshlangʻich zaxirani ham kiritishingiz mumkin. "Tugallanmagan" tegi qatorda bitta parametr qiymati yetishmayotganini bildiradi.',
'VG_List_Title' => 'Oddiy roʻyxat rejimi',
'VG_List_Text' => 'Qator qoʻshish uchun variant nomini yozing va Enter tugmasini bosing (yoki Qoʻshish tugmasini bosing), soʻng uning kodi va narxlarini toʻldiring. Bu klassik usul boʻlib, mavjud mahsulotlar uchun saqlanib qoladi.',
'VG_Edit_Title' => 'Keyinroq tahrirlash',
'VG_Edit_1' => 'Qiymat qoʻshing va "Variantlarni yaratish" tugmasini bosing: faqat yetishmayotgan kombinatsiyalar qoʻshiladi. Mavjud qatorlar oʻz kodlari, narxlari va tarixini saqlab qoladi.',
'VG_Edit_2' => 'Qiymat yoki parametrni olib tashlash undan foydalanadigan qatorlarni olib tashlaydi. Allaqachon saqlangan qatorlar tasdiqlashdan keyin mahsulotni saqlaganingizda oʻchiriladi.',
'VG_Edit_3' => 'Hali zaxirasi bor variantni olib tashlab boʻlmaydi. Avval uning zaxirasini tuzating yoki koʻchiring.',
'VG_Edit_4' => '"Oddiy roʻyxat" ga oʻtish qatorlar va ularning nomlarini saqlaydi, lekin parametr taʼriflarini olib tashlaydi.',
'VG_Store_Title' => 'Onlayn doʻkonda',
