'Upd_Note_Permission_Only' => '2-eslatma: tizimni faqat administrator yoki "{perm}" ruxsatiga ega foydalanuvchi yangilashi mumkin',
'Upd_Manual_Step_Backup_Db' => 'Maʼlumotlar bazangizning zaxira nusxasini oling. {backup} ga oʻting, Zaxira nusxa yaratish tugmasini bosing — uni {path} da topasiz — yoki maʼlumotlar bazangizni PhpMyAdmin dan eksport qilib, kompyuteringizga saqlang.',
