'Upd_Note_Blank_Pages' => 'Eslatma: Agar biror sahifa yuklanmasa yoki boʻsh boʻlsa, brauzer keshini tozalaganingizga ishonch hosil qiling.',
'Upd_Guide_Before_Title' => '1. Yangilashdan oldin',
'Upd_Guide_Before_Download' => 'Ilovaning {package} CodeCanyon hisobingizdan ({path}) yuklab oling. Uni arxivdan chiqarmang — yangilagichga ZIP aynan yuklab olingan holida kerak.',
'Upd_Latest_Full_Zip' => 'eng soʻnggi toʻliq ZIP paketini',
'Upd_Guide_Before_Admin' => '{perm} ruxsatiga ega administrator sifatida tizimga kirganingizga ishonch hosil qiling. Yangilagichni boshqa hech kim koʻra olmaydi va ishga tushira olmaydi.',
'Upd_Guide_Before_Quiet' => 'Tinch vaqtni tanlang: yangilash davomida ilova qisqa vaqtga texnik xizmat rejimiga oʻtadi va boshqa foydalanuvchilar kira olmaydi.',
'Upd_Guide_Before_No_Manual' => 'Qoʻlda zaxira nusxa olish, fayllarni arxivdan chiqarish, buyruqlarni ishga tushirish, konfiguratsiya fayllarini tahrirlash yoki maʼlumotlar bazasiga tegish shart {not} — yangilagich bularning barchasini avtomatik bajaradi. (Albatta, qoʻshimcha qoʻlda zaxira nusxa hech qachon zarar qilmaydi.)',
'Upd_Not' => 'emas',
'Upd_Guide_Code_Overwritten' => 'Agar ilova kodini qoʻlda oʻzgartirgan boʻlsangiz, oʻzgarishlaringiz yangilanish bilan qayta yoziladi. Maʼlumotlaringiz, yuklangan fayllar, sozlamalar va .env doim saqlanib qoladi.',
'Upd_Guide_Running_Title' => '2. Yangilashni ishga tushirish',
'Upd_Guide_Run_Open' => '{path} ni (shu sahifani) oching va {tab} yorligʻida qoling.',
'Upd_Guide_Run_Upload' => '{upload}: yuklab olingan paketni yuklash maydoniga bosing yoki sudrab tashlang. Katta fayllar kichik qismlarga boʻlib yuklanadi, shuning uchun bu yuklash chegarasi past boʻlgan umumiy hostingda ham ishlaydi. Nazorat summasi buzilgan yoki toʻliq boʻlmagan yuklashlardan himoya qiladi.',
'Upd_Upload_The_Zip' => 'ZIP ni yuklang',
'Upd_Guide_Run_Validation' => '{auto} yuklashdan keyin (uni {button} tugmasi bilan qayta ishga tushirishingiz mumkin). Tizim quyidagilarni tekshiradi: ZIP yaxlitligi, paket tuzilmasi va toʻliqligi, versiya mosligi (pastki versiyaga qaytish rad etiladi), talab qilinadigan PHP versiyasi va kengaytmalari, fayl ruxsatlari, boʻsh disk joyi, maʼlumotlar bazasi ulanishi, konfiguratsiya va boshqa yangilash ishlamayotganligi.',
'Upd_Validation_Runs_Automatically' => 'Tekshiruv avtomatik ishga tushadi',
'Upd_Guide_Run_Review' => '{panel} panelini koʻrib chiqing. {button} tugmasi faqat barcha muhim tekshiruvlar oʻtganda paydo boʻladi. Agar tekshiruv muvaffaqiyatsiz boʻlsa, xabar nimani tuzatish kerakligini aniq aytadi.',
'Upd_Guide_Run_Click' => '{button} ni bosing va tasdiqlang. Keyin shunchaki {keep} va jarayon chizigʻini kuzating. Tizim quyidagilarni tartib bilan bajaradi:',
'Upd_Keep_Page_Open' => 'bu sahifani ochiq qoldiring',
'Upd_Guide_Phase_Backup' => '{label} — maʼlumotlar bazasining toʻliq dampi, yangilanish oʻzgartirishi mumkin boʻlgan barcha ilova fayllarining ZIP arxivi va {env} nusxasi yaratiladi va {verified}. Yuklangan fayllaringiz ({images}) va {storage} yangilanish tomonidan hech qachon oʻzgartirilmaydi, shuning uchun ular arxivlanmaydi. Agar zaxira nusxa yaratib boʻlmasa, yangilash shu yerda toʻxtaydi va hech narsa oʻzgarmaydi.',
'Upd_Verified' => 'tekshiriladi',
'Upd_Guide_Phase_Prepare' => '{label} — yangi versiya oraliq hududga chiqariladi va yana tekshiriladi. Ishlayotgan ilovaga hali tegilmaydi.',
'Upd_Guide_Phase_Maintenance' => '{label} — texnik xizmat rejimi yoqiladi; tashrif buyuruvchilar "Tez orada qaytamiz" ekranini koʻradi.',
'Upd_Guide_Phase_Files' => '{label} — yangi fayllar deyarli bir zumda almashtiriladi; eski fayllar orqaga qaytarish uchun alohida saqlanadi. Himoyalangan yoʻllar ({env}, {storage}, {images}) hech qachon almashtirilmaydi.',
'Upd_Guide_Phase_Database' => '{label} — migratsiyalar bajariladi, soʻngra ruxsatlar, tarjimalar va shablonlar yangilanadi.',
'Upd_Guide_Phase_Cache' => '{label} — barcha keshlar tozalanadi va qayta quriladi.',
'Upd_Guide_Phase_Verify' => '{label} — holat tekshiruvlari yangi versiya ishga tushishini, maʼlumotlar bazasi ishlashini, barcha migratsiyalar bajarilganini va konfiguratsiya toʻgʻriligini tasdiqlaydi.',
'Upd_Guide_Phase_Done' => '{label} — texnik xizmat rejimi oʻchiriladi va vaqtinchalik fayllar tozalanadi.',
'Upd_Guide_Run_Success' => '{success} ni koʻrganingizda {reload} ni bosing va yangi boshqaruv paneli resurslari yuklanishi uchun brauzeringizni toʻliq yangilang ({keys}).',
'Upd_Update_Successful_Short' => 'Yangilash muvaffaqiyatli',
'Upd_Guide_No_Internet' => 'Yangilash davomida internet ulanishi kerak emas — hamma narsa yuklangan ZIP dan olinadi. Ulanish uzilishi yoki brauzerni yopish yangilashni BUZMAYDI: server aynan qayerda toʻxtaganini eslab qoladi.',
'Upd_Guide_Wrong_Title' => '3. Agar biror narsa notoʻgʻri ketsa',
'Upd_Guide_Wrong_Rollback' => '{label} — agar fayllar oʻzgara boshlagandan keyin biror narsa muvaffaqiyatsiz boʻlsa (arxivdan chiqarish xatosi, migratsiya xatosi, holat tekshiruvi muvaffaqiyatsizligi, disk toʻlishi, …), tizim tekshirilgan zaxira nusxadan oldingi fayllar va maʼlumotlar bazasini avtomatik tiklaydi, texnik xizmat rejimini oʻchiradi va {message} haqida xabar beradi. Siz aynan boshlagan joyingizga qaytasiz.',
'Upd_Automatic_Rollback' => 'Avtomatik orqaga qaytarish',
'Upd_Failed_Previous_Restored' => 'Yangilash muvaffaqiyatsiz — oldingi versiya tiklandi',
'Upd_Guide_Wrong_Interrupted' => '{label} (server qayta ishga tushishi, taym-aut, brauzer yopilishi, elektr uzilishi) — bu sahifani qayta ochganingizda qizil banner ikkita xavfsiz tanlovni taklif qiladi: {resume} (aynan toʻxtagan qadamdan davom ettiradi) yoki {rollback} (oldingi versiyani zaxira nusxadan tiklaydi).',
'Upd_Interrupted_Update' => 'Toʻxtatilgan yangilash',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} manzilidagi mustaqil {console} dan foydalaning. U sayt texnik xizmat rejimida boʻlganda yoki boshqaruv paneli resurslari buzilganda ham ishlaydi va xuddi shunday Davom ettirish / Orqaga qaytarish amallarini taklif qiladi. Texnik xizmat ekranining pastida ham koʻzga tashlanmaydigan "Administrator kirishi" havolasi bor.',
'Upd_Admin_Unreachable' => 'Boshqaruv paneli ochilmayapti',
'Upd_Recovery_Console' => 'tiklash konsoli',
'Upd_Guide_Wrong_Locked_Out' => '{label} — yangilash ishlayotganda bu sahifa {link} ni koʻrsatadi. Agar qayta kirishingiz kerak boʻlsa (masalan, sessiyangiz tugaganidan keyin), uni saqlab qoʻying; u sizni texnik xizmat ekranidan oʻtkazadi, shunda qayta kirishingiz mumkin.',
'Upd_Locked_Out_Maintenance' => 'Texnik xizmat rejimi tufayli kira olmayapsiz',
'Upd_Bypass_Link' => 'chetlab oʻtish havolasi',
'Upd_Guide_Wrong_Concurrent' => '{label} — ular {message} ni koʻradi. Bir vaqtning oʻzida faqat bitta yangilash ishlashi mumkin.',
'Upd_Another_Admin_Updating' => 'Boshqa administrator bir vaqtda yangilashga urinmoqda',
'Upd_Guide_Backups_Title' => '4. Zaxira nusxalar va tiklash',
'Upd_Guide_Backups_Created' => 'Har bir yangilash biror narsaga tegishdan {before} zaxira nusxa yaratadi: yangilanish almashtirishi mumkin boʻlgan barcha ilova fayllari, {env} nusxasi va maʼlumotlar bazasining toʻliq dampi. Yuklangan fayllar va {storage} yangilanish tomonidan hech qachon oʻzgartirilmaydi va shuning uchun unga kirmaydi — ularning zaxira nusxasini oʻzingiz saqlang. Zaxira nusxalar {path} da saqlanadi va hech qachon vebdan ochilmaydi.',
'Upd_Before' => 'oldin',
'Upd_Guide_Backups_Panel' => '{tab} yorligʻidagi {panel} paneli ularni sana, versiya va hajmi bilan koʻrsatadi. U yerdan istalgan toʻliq zaxira nusxani {restore} (fayllar + maʼlumotlar bazasi — avval joriy maʼlumotlar bazasining xavfsizlik nusxasi olinadi) yoki eskilarini {delete} mumkin.',
'Upd_Restore_Verb' => 'tiklash',
'Upd_Delete_Verb' => 'oʻchirish',
'Upd_Guide_Backups_Retention' => 'Nechta zaxira nusxa saqlanishini tanlash uchun {keep} dan foydalaning; eskilari har bir muvaffaqiyatli yangilashdan keyin avtomatik olib tashlanadi. Yagona qolgan toʻliq zaxira nusxani hech qachon oʻchirib boʻlmaydi — sizda doim orqaga qaytish yoʻli qoladi.',
'Upd_Guide_Manual_Title' => '5. Qoʻlda yangilash (zaxira usul)',
'Upd_Guide_Manual_Text' => 'Agar qoʻlda yangilashni afzal koʻrsangiz yoki serveringizda yuklagichdan foydalanib boʻlmasa, ushbu sahifaning {tab} yorligʻidagi bosqichma-bosqich koʻrsatmalarga amal qiling.',
'Upd_Guide_Clear_Cache_First' => 'Agar biror yangilashdan keyin sahifalar buzilgan yoki boʻsh koʻrinsa, avval brauzer keshini tozalang — deyarli har doim sabab shunda.',
'Upd_Restore_Backup_Confirm' => 'Bu zaxira nusxa tiklansinmi? Joriy fayllar va joriy maʼlumotlar bazasi zaxira nusxa bilan almashtiriladi. Avval joriy maʼlumotlar bazasining xavfsizlik nusxasi olinadi. (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce doʻkoni ERP bilan qanday hamohang boʻlib turadi. Quyidagi cron qatorlari ushbu server uchun tuzilgan, shuning uchun ularni toʻgʻridan-toʻgʻri nusxalab qoʻyish mumkin.',
'Woo_Guide_Ways_Note' => 'Shopify dan farqli oʻlaroq, WooCommerce ERP ga oʻzi hech narsa yubormaydi — bu yerda webhook qabul qiluvchi yoʻq, shuning uchun {in} keladigan hamma narsa jadval boʻyicha keladi. Faqat {out} chiqadigan zaxira darhol boʻlishi mumkin.',
'Woo_In' => 'ichkariga',
'Woo_Out' => 'tashqariga',
'Woo_Guide_Both_Ways_Title' => 'Ikkala yoʻnalish uchun avval bu kerak',
'Woo_Api_Keys' => 'API kalitlari',
'Woo_Guide_Api_Keys_Text' => '{path}, ruxsat {perm}. Consumer key va secret ni doʻkon URL manzili bilan birga — oxirida qiya chiziqsiz sayt manzilingiz, masalan {example} — {settings} yorligʻiga nusxalang.',
'Woo_Credentials_Saved' => 'hisob maʼlumotlari saqlangan',
'Woo_Not_Configured_Yet' => 'hali sozlanmagan',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress ilova paroli (ixtiyoriy)',
'Woo_Guide_Wp_App_Password_Text' => 'Faqat mahsulot rasmlari uchun ishlatiladi. WooCommerce API mahsulotlar, zaxira, kategoriyalar, brendlar, mijozlar va buyurtmalarni koʻchiradi; WordPress API esa Media kutubxonasida qidiradi va hali mavjud boʻlmagan rasmni yuklaydi.',
'Woo_Guide_Wp_App_Password_Note' => 'Media bilan ishlay oladigan WordPress foydalanuvchisidan foydalaning va parolni {path} da yarating. Ikkala maydonni boʻsh qoldirsangiz ham hamma narsa sinxronlanadi — faqat rasm biriktirish oʻtkazib yuboriladi.',
'Woo_Guide_Pick_Way_Title' => 'Keyin qanday hamohang boʻlishini tanlang',
'Woo_Right_Away' => 'Darhol',
'Woo_Stock_Live' => 'zaxira jonli',
'Woo_Stock_Not_Live' => 'zaxira jonli emas',
'Woo_Guide_Realtime_Lead' => 'Faqat bir yoʻnalish: ERP dan chiqadigan zaxira va mahsulotlar. WooCommerce da qilingan buyurtmalar va mahsulot tahrirlari baribir jadval boʻyicha keladi — boshqa yorliqqa qarang.',
'Woo_Push_Stock_On_Change' => 'Zaxira oʻzgarishi bilan darhol yuborish',
'Woo_Setting_People_Miss' => 'Bu koʻpchilik eʼtibordan chetda qoldiradigan sozlama',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS savdosi WooCommerce ga oʻz-oʻzidan {not}. Oʻchirilgan boʻlsa, doʻkon bu haqda faqat keyingi zaxira sinxronlashda — standart boʻyicha bir soatda — biladi va shu oraliqda kassada allaqachon sotilgan birlikni sotib yuborishi mumkin.',
'Woo_Does_Not' => 'yetib bormaydi',
'Woo_Guide_Tick_Instant' => '{settings} yorligʻida {option} belgisini qoʻying. Butun sozlash shu — worker ham, cron ham kerak emas. Shundan soʻng har bir savdo, qaytarish, tuzatish, koʻchirish va qabul qilingan xarid savdo saqlangandan soʻng darhol faqat oʻsha mahsulotlar uchun yuborish amalga oshiradi, yigirma qatorli savdo esa yigirmata emas, bitta yuborishga teng. Kassa uni hech qachon kutmaydi.',
'Woo_Currently' => 'Hozirda:',
'Woo_Instant_On_Text' => 'yoqilgan — zaxira oʻzgarishda yuboriladi',
'Woo_Instant_Off_Text' => 'oʻchirilgan — zaxira faqat jadval boʻyicha',
'Woo_Guide_Instant_Note' => 'Faqat WooCommerce ga allaqachon bogʻlangan mahsulotlar yuboriladi — hech qachon sinxronlanmagan mahsulotning doʻkonda tuzatiladigan narsasi yoʻq. Variantli mahsulotlar ota mahsulot orqali oʻtadi, kombo esa uning istalgan komponenti harakatlanganda qayta yuboriladi. Ommaviy amallar (mahsulotni oʻchirish, omborni tozalash) zaxirani hodisa chaqirmasdan yozadi — bu soatlik zaxira sinxronlashni ham saqlashning bir sababi.',
'Woo_Push_Products_On_Save' => 'Mahsulotlarni saqlanishi bilan darhol yuborish',
'Woo_Guide_Tick_Auto_Products' => '{settings} yorligʻida {option} belgisini qoʻying va Stocky da yaratilgan, tahrirlangan yoki nusxalangan mahsulot saqlanganidan soʻng darhol WooCommerce ga yuboriladi — tafsilotlar, narx, variantlar va rasmlar, soʻngra uning zaxirasi. Yangi mahsulot tungi mahsulotlar sinxronlashini kutmasdan doʻkonda darhol yaratiladi.',
'Woo_On' => 'yoqilgan',
'Woo_Off' => 'oʻchirilgan',
'Woo_Guide_Bulk_Imports_Note' => 'Ommaviy importlar birma-bir yuborilmaydi — importdan keyin mahsulotlar sinxronlashini ishga tushiring. Yuborilgan mahsulot toʻgʻri kategoriyaga tushishi uchun avval kategoriyalar va brendlarni sinxronlang.',
'Woo_Nothing_Else_To_Install' => 'Boshqa hech narsa oʻrnatish shart emas',
'Woo_Guide_Same_Process' => 'Navbat worker i ham, cron yozuvi ham yoʻq. Yuborish savdoga xizmat koʻrsatgan jarayonning oʻzida, javob qaytarilgandan {after} ishlaydi, shuning uchun kassa hech qachon WooCommerce ni kutmaydi. Yuborishlar hech qachon ustma-ust tushmaydi: biri ishlayotganda kiritilgan oʻzgarishlar uni kutadi va undan keyin darhol yuboriladi.',
'Woo_After' => 'keyin',
'Woo_Guide_Shop_Stops_Answering' => 'Javob bermay qolgan doʻkon sakkiz soniyadan keyin tark etiladi va har bir savdo uni yana kutmasligi uchun yuborishlar besh daqiqaga toʻxtatiladi; shu orada kelgan oʻzgarishlar pauzadan keyingi birinchi yuborish bilan ketadi, soatlik zaxira sinxronlash esa baribir yetib oladi. Har bir pauza Jurnallar yorligʻida qayd etiladi.',
'Woo_Guide_Artisan_Exception' => 'Bitta istisno: artisan buyrugʻi orqali qilingan zaxira oʻzgarishida keyin keladigan javob yoʻq, shuning uchun u {queue} navbatiga qoʻyiladi. Ularning ham tezda yuborilishi uchun ushbu navbatni boʻshating:',
'Woo_Cron_Line_Copied' => 'Cron qatori nusxalandi',
'Woo_Command_Copied' => 'Buyruq nusxalandi',
'Woo_Guide_Not_Woo_Queue' => 'Ataylab {queue} navbati emas: u soatlab davom etadigan katalog paketlarini tashiydi va uning ortida navbatga qoʻyilgan darhol yuborish darhol boʻlmay qoladi.',
'Woo_On_A_Schedule' => 'Jadval boʻyicha',
'Woo_Guide_Scheduled_Lead' => 'Hamma narsa vaqti-vaqti bilan ikkala yoʻnalishda qayta tekshiriladi. Buyurtmalar ERP ga shunday yetib keladi, katalog shunday chop etiladi va tezkor yoʻl oʻtkazib yuborgan narsalar shunday tuzatiladi. Har bir vazifaning oʻz cron yozuvi bor, shuning uchun faqat keraklisini ishga tushirasiz.',
'Woo_Guide_Sync_Drains_Queue' => '{command} ishlayotganda oʻz navbatini oʻzi boʻshatadi, shuning uchun bu qatorlarga alohida worker kerak emas. Windows da Task Scheduler dan {program} dasturi va xuddi shu argumentlar bilan, {path} da ishga tushirilgan holda foydalaning.',
'Woo_Or_No_Cron' => 'Yoki umuman cron siz',
'Woo_Guide_No_Cron_Text' => 'Bu yerdagi har bir yorliq talab boʻyicha sinxronlaydi va qoʻlda sinxronlash sahifa ochiq turganda oʻz paketlarini oʻzi boʻshatadi — shuning uchun kichik doʻkon umuman cron yozuvisiz ishlashi mumkin. Yoʻqotadiganingiz — hech kim qaramayotganda sodir boʻladigan hamma narsa: buyurtmalar faqat kimdir tugmani bosganda keladi.',
'Woo_Commands_Worth_Knowing' => 'Bilish foydali buyruqlar',
'Woo_Worth_Knowing' => 'Bilish foydali',
'Woo_Guide_Changing_Url_Clears' => 'Doʻkon URL manzili yoki API kalitlarini oʻzgartirish barcha moslashtirishlarni tozalaydi — mahsulotlar, kategoriyalar, brendlar va mijozlar yangi doʻkonga qaytadan sinxronlanadi.',
'Woo_Guide_Keep_Skus' => 'Stocky va WooCommerce oʻrtasida SKU larni bir xil saqlang: aynan shu dublikatlarning oldini oladi va qayta bogʻlashni xavfsiz qiladi.',
