'Woo_No_Shop_Connected_Desc' => 'Quyidagilarning barchasi baribir amal qiladi — WooCommerce sozlamalari sahifasida doʻkon URL manzili va API kalitlarini kiriting, soʻngra qaytib keling.',
'Woo_Wp_Username' => 'WordPress foydalanuvchi nomi',
'Woo_Wp_App_Password' => 'WordPress ilova paroli',
'Woo_Settings_Instant_Hint' => 'Savdo, qaytarish yoki tuzatish saqlangan zahoti faqat oʻsha mahsulotlar uchun zaxira yuboradi, shuning uchun doʻkon keyingi soatlik zaxira sinxronlashda emas, soniyalar ichida toʻgʻri boʻladi. Boshqa hech narsa oʻrnatish shart emas — yuborish savdoga javob berilgandan keyin ishlaydi, shuning uchun kassa hech qachon WooCommerce ni kutmaydi. Batafsil {guide} yorligʻida.',
'Woo_Settings_Instant_Off_Alert' => 'Oʻchirilgan boʻlsa, POS savdosi WooCommerce ga faqat keyingi zaxira sinxronlashda — bir soatgacha kechikib — yetib boradi.',
'Woo_Settings_Auto_Products_Hint' => 'Stocky da yaratilgan, tahrirlangan yoki nusxalangan mahsulot mahsulotlar sinxronlashini kutmasdan saqlanganidan soʻng darhol WooCommerce ga yuboriladi — tafsilotlar, narx, variantlar, rasmlar, soʻngra uning zaxirasi. Ommaviy importlar yuborilmaydi; importdan keyin mahsulotlar sinxronlashini ishga tushiring.',
'Woo_Sync_Tuning' => 'Sinxronlashni sozlash',
'Woo_Sync_Tuning_Intro' => 'Standart qiymatlar koʻpchilik doʻkonlarga mos keladi. Ularni faqat sinxronlash sekin boʻlsa yoki hostingingizda taym-aut boʻlsa oʻzgartiring. Har bir qiymat xavfsiz oraliq bilan cheklangan va maydonni tozalash uning standart qiymatini tiklaydi.',
'Woo_Setting_This_Up' => 'Buni sozlash',
'Woo_Setting_This_Up_Text' => 'API kalitlarini olish, WordPress ilova paroli nima uchun kerakligi, rejalashtirilgan sinxronlashlar uchun cron yozuvlari va zaxira oʻzgarishi bilan darhol doʻkonga yetib borishini qanday taʼminlash — barchasi, ushbu serverning nusxalashga tayyor cron qatorlari bilan, Qoʻllanma yorligʻida joylashgan. Bitta nusxa, shuning uchun u modul aslida nima qilishidan farq qilib qolmaydi.',
