'Telegram_G_A_Title' => 'Darhol — hech narsa oʻrnatish shart emas',
'Telegram_G_A_Body' => 'Stocky da — POS da yoki boshqaruv panelida — saqlangan savdo, xarid, toʻlov yoki xarajat saqlangandan {after}, ayni soʻrov ichida Telegram ga yuboriladi. Cron yozuvi ham, navbat worker i ham kerak emas va kassir hech qachon Telegram ni kutmaydi: xabar ketayotganda savdoga allaqachon javob berilgan boʻladi.',
