'Telegram_G_B_Body' => 'Ikki turdagi xabar Telegram ning oʻz navbatida kutadi: muvaffaqiyatsiz yuborish (Telegram bir lahzaga mavjud boʻlmaganda), u keyingi bir necha daqiqa ichida yana uch martagacha qayta uriniladi; va boshqaruv panelidan tashqarida yuzaga kelgan hodisalar — WooCommerce yoki Shopify dan import qilingan buyurtmalar, artisan buyruqlari. Bu cron yozuvi ularni yuboradi, boshqa hech narsani emas:',
'Telegram_G_Cron_Note' => 'Har daqiqa toʻgʻri: kutayotgan narsa boʻlmasa, ishga tushirish darhol tugaydi. cPanel da bu {cronJobs} ga qoʻyiladi — agar {php} eskiroq boʻlsa, PHP 8.2+ ga toʻliq yoʻldan foydalaning. Windows da Task Scheduler dan {program} dasturi, {args} argumentlari bilan, {path} da ishga tushirilgan holda foydalaning.',
