'Xero_Push_Customers_Desc' => 'Har bir mijoz uchun Xero kontaktini yaratadi yoki yangilaydi. Nomi Xero da allaqachon mavjud boʻlgan mijoz oʻsha kontaktga bogʻlanadi.',
'Xero_Push_Customers' => 'Mijozlarni yuborish',
'Xero_Push_Sales_Invoices' => 'Savdolarni hisob-faktura sifatida yuborish',
'Xero_Push_Invoices_Desc' => 'Har bir savdo uchun bitta AUTHORISED hisob-faktura yaratadi (hisob-faktura raqami = savdo Ref), Xero jami summasi savdo jami summasiga mos kelishi uchun savdo qatorlari hamda yetkazib berish, chegirma va soliq qatorlari bilan. Xero da allaqachon mavjud savdolar oʻtkazib yuboriladi — hisob-fakturalar hech qachon tahrirlanmaydi. Yetishmayotgan kontaktlar jarayonda yaratiladi.',
'Xero_Push_Invoices' => 'Hisob-fakturalarni yuborish',
