'Xero_Reset_Contact_Links' => 'Kontakt bogʻlanishlarini tiklash',
'Xero_Guide_1' => '{link} da ({menu}) {webApp} yarating.',
'Xero_Guide_2' => 'Ulanish yorligʻida koʻrsatilgan redirect URI ni roʻyxatdan oʻtkazing.',
'Xero_Guide_3' => 'Ilovaning {clientId} ini nusxalang va {clientSecret} yarating; ikkalasini shu yerga qoʻying va saqlang.',
'Xero_Guide_4' => '{connect} ni bosing, tizimga kiring va ulanadigan tashkilotni tanlang.',
'Xero_Guide_5' => 'Hisob kodlarini tekshiring: savdo hisobi hisob-faktura qatorlarini oladi; toʻlangan savdolar toʻlovlarni ham qayd etishi kerak boʻlsa, bank hisobi kodini belgilang.',
'Xero_Guide_6' => 'Avval mijozlarni, soʻngra hisob-fakturalarni yuboring. Hisob-faktura raqamlari savdo Ref lari boʻladi, shuning uchun bogʻlanishlar tiklansa ham Xero dublikatlarni rad etadi.',
'Xero_Amounts_Title' => 'Summalar soliq bilan birga oʻzgarishsiz yuboriladi',
'Xero_Amounts_Desc' => 'Hisob-fakturalar savdoni aynan aks ettiruvchi NoTax qatorlardan foydalanadi (mahsulotlar + yetkazib berish − chegirma + soliq), shuning uchun Xero jami summalari har doim Stocky jami summalariga teng. Buxgalteringiz soliq va yetkazib berish qatorlarini Xero ichida tegishli hisoblarga qayta moslashi mumkin.',
'Xero_Org_Connected' => 'Xero tashkiloti ulandi.',
'Jumia_Hero_Title' => 'Jumia marketpleysi sinxronlashi',
'Jumia_Hero_Desc' => 'Narx va zaxirani Jumia Seller Center eʼlonlaringizga yuboring va marketpleys buyurtmalarini savdo sifatida import qiling.',
'Jumia_Api_Url_Label' => 'API URL (mamlakatingizning Seller Center endpoint i)',
'Jumia_Account_Email' => 'Hisob emaili (User ID)',
'Jumia_Api_Key' => 'API kaliti',
'Jumia_Prices_Stock' => 'Narxlar va zaxira',
'Jumia_Push_Prices_Stock_Title' => 'Narx va zaxirani Jumia ga yuborish',
'Jumia_Push_Prices_Stock_Desc' => 'SKU si Jumia eʼlonining {sku} iga mos keladigan har bir mahsulot (va variant) uchun joriy narx va miqdorni yuboradi. Yangilanishlar Seller Center feed lari sifatida yuboriladi va asinxron qoʻllaniladi — feed ID Jurnallar yorligʻida qayd etiladi, alohida elementlar boʻyicha rad etishlar esa Seller Center ning feed holati ekranida koʻrinadi.',
'Jumia_Push_Prices_Stock' => 'Narx va zaxirani yuborish',
'Jumia_Pull_Orders_Desc' => 'Marketpleys buyurtmalarini savdo sifatida ({ref} kabi maʼlumotnomalar bilan) import qiladi, Seller SKU boʻyicha mahsulotlaringizga moslashtiriladi. Allaqachon import qilingan va bekor qilingan buyurtmalar oʻtkazib yuboriladi, shuning uchun muntazam tortish xavfsiz. Toʻlovlar faqat yetkazilgan buyurtmalar uchun toʻlangan deb belgilanadi (Jumia da asosan COD).',
'Jumia_Guide_1' => 'Jumia {sellerCenter} da {menu} ni oching va API kalitini yarating.',
'Jumia_Guide_2' => 'Mamlakatingiz API URL manzilini (masalan, Nigeriya uchun {ng}, Keniya uchun {ke}, Misr uchun {eg}), Seller Center hisobingiz emailini va kalitni kiriting — soʻngra {test} ni ishga tushiring.',
'Jumia_Guide_3' => 'Har bir Jumia eʼlonining {sku} i Stocky mahsulot kodiga teng ekanligiga ishonch hosil qiling — bu zaxira yuborish va buyurtmalarni moslashtirish uchun ishlatiladigan identifikator.',
'Jumia_Guide_4' => 'Inventar oʻzgarganidan keyin narx va zaxirani yuboring; buyurtmalarni muntazam torting (bu API da Jumia webhooklari yoʻq).',
'Jumia_Guide_5' => 'Yangi eʼlonlar yaratish Seller Center da qoladi — Jumia kategoriyaga xos atributlar va rasmlarni koʻrib chiqishni talab qiladi, buni faqat ularning portali yaxshi bajaradi.',
'Mailchimp_Hero_Title' => 'Mailchimp auditoriyasini sinxronlash',
'Mailchimp_Hero_Desc' => 'Haqiqiy mijozlar bazangizda email kampaniyalarini oʻtkazish uchun Mailchimp auditoriyasini mijozlaringiz bilan toʻldirib boring.',
