'Mailchimp_With_Email' => 'Emaili borlar',
'Mailchimp_Push_Desc' => 'Email manzili bor har bir mijozni tanlangan auditoriyaga qoʻshadi yoki yangilaydi (ism va telefon bilan birga). Mavjud aʼzolar obuna holatini saqlaydi — obunani bekor qilgan hech kim qayta obuna qilinmaydi. Emaili yoʻq mijozlar chetda qoladi.',
