'Mailchimp_Guide_3' => 'Mijozlaringiz marketing emaillariga allaqachon rozilik bermagan boʻlsa, {doubleOptIn} ni yoqilgan holda qoldiring.',
'Mailchimp_Double_Optin_Term' => 'ikki bosqichli tasdiq',
'Mailchimp_Guide_4' => 'Dastlabki toʻldirish uchun {push} ni ishga tushiring; yangi mijozlar avtomatik qoʻshilishi uchun {autoSync} ni yoqing.',
