'Shopify_G_Lead_Store' => 'Bu doʻkon hamohang boʻlib turishi uchun nima kerak. Bu yerdagi hamma narsa aynan shu doʻkonga tegishli — yoʻllar va id lar haqiqiy, shuning uchun buyruqlarni toʻgʻridan-toʻgʻri serverga nusxalash mumkin.',
'Shopify_G_Lead_Generic' => 'Shopify doʻkoni ERP bilan qanday hamohang boʻlib turadi. Uning oʻz holatini koʻrish uchun yuqorida doʻkonni tanlang yoki shunday oʻqing — cron qatori va webhook URL manzili qaysi doʻkonni ulasangiz ham bir xil.',
'Shopify_G_Ways_Note' => 'Koʻpchilik doʻkonlar ikkalasini ham ishlatadi: birinchisi doʻkonni daqiqama-daqiqa yangilab turadi, ikkinchisi birinchisi oʻtkazib yuborgan narsalarni ushlaydi — hech qachon kelmagan webhook, toʻgʻridan-toʻgʻri Shopify boshqaruv panelida qilingan tahrir, sayt ishlamagan kecha.',
'Shopify_G_Both_Need' => 'Ikkala yoʻnalish uchun avval bu kerak',
'Shopify_G_Credentials' => 'Shopify hisob maʼlumotlari',
'Shopify_G_Cred_Intro' => '2026-yil yanvaridan boshlab Shopify boshqaruv panelida maxsus ilovalar yaratmaydi, shuning uchun ulanishning ikki turi mavjud:',
'Shopify_G_Cred_DevDash' => '{app} (hozir ulangan istalgan doʻkon) — {path}. Bu doʻkon sinxronlaydigan narsalar uchun Admin API ruxsatlarini bering, ilovani doʻkonga oʻrnating, soʻngra ilovaning Settings sahifasidan {clientId} va {clientSecret} ni {where} ga nusxalang. ERP ularni oʻzi kirish tokeniga almashtiradi va har 24 soatda muddati tugashidan oldin yangilaydi. Client secret webhooklarni ham imzolaydi, shuning uchun boshqa hech narsa kerak emas. Ilova va doʻkon bitta Shopify tashkilotida boʻlishi kerak.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard ilovasi',
'Shopify_G_Cred_Legacy' => '{app} (2026-yilgacha boshqaruv panelida yaratilgan) — oʻzining {token} ({prefix}) va webhook imzo secret i sifatida {secret} bilan oʻzgarishsiz ishlashda davom etadi. Bu token bilan bir xil qiymat emas va ularni almashtirib yuborish webhooklar rad etilishining odatiy sababidir.',
'Shopify_G_Legacy_App' => 'Eski maxsus ilova',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'saqlangan',
'Shopify_G_Missing_Refused' => 'yoʻq — yetkazmalar rad etiladi',
'Shopify_G_Where_Data_Desc' => '{path} Bu doʻkon zaxirasini sotadigan ERP ombori va bu zaxira yoziladigan Shopify joylashuvi. Inventar sinxronlash ham, buyurtma importi ham ularsiz ishlamaydi.',
'Shopify_G_Currently' => 'Hozirda: ombor {warehouse}, joylashuv {location}',
'Shopify_G_Not_Set_Lower' => 'belgilanmagan',
'Shopify_G_Ready' => 'tayyor',
'Shopify_G_Incomplete' => 'toʻliq emas',
'Shopify_G_Manual_Syncs' => 'Qoʻlda boshlanadigan sinxronlashlar',
'Shopify_G_Manual_Desc' => '{centre} dan boshlangan sinxronlash darhol javob beradi va fonda, har biri oldingisi toʻxtagan joydan davom etadigan qisqa boʻlaklarda ishlaydi. Uzoq veb-soʻrovlarni tugatadigan hosting (LiteSpeed, nginx, load balancer) katta katalogni hech qachon yarim yoʻlda uzmaydi va sahifani yopish uni toʻxtatmaydi. Buning uchun worker yana bitta cron qatoridir:',
'Shopify_G_Cron_Copied' => 'Cron qatori nusxalandi',
'Shopify_G_Manual_Note' => 'Usiz ham sinxronlash yakunlanadi, lekin faqat Sinxronlash markazi sahifasi ochiq turganda: bir necha soniya ichida hech bir worker ishga tushirishni olmasa, sahifa uni oʻzi, bir vaqtda bitta qisqa soʻrov bilan davom ettiradi. Windows da Task Scheduler dan har daqiqada foydalaning: dastur {program}, argumentlar {args}, {dir} da ishga tushiriladi.',
'Shopify_G_Then_Pick' => 'Keyin qanday hamohang boʻlishini tanlang',
'Shopify_G_Right_Away' => 'Darhol',
'Shopify_G_Stock_Live' => 'zaxira jonli',
'Shopify_G_Stock_Not_Live' => 'zaxira jonli emas',
'Shopify_G_Realtime_Lead' => 'Har bir oʻzgarish sodir boʻlishi bilan, soniyalar ichida yuboriladi. Ikki qism va ular alohida kalitlar: {webhooks} doʻkonning oʻz hodisalarini ichkariga olib keladi, {push} esa zaxirani tashqariga yuboradi.',
'Shopify_G_Webhooks_Lower' => 'webhooklar',
'Shopify_G_Instant_Push_Lower' => 'darhol zaxira yuborish',
'Shopify_G_Webhooks_In' => 'Webhooklar — doʻkon → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify da qilingan buyurtmalar, buyurtma holati oʻzgarishlari va mahsulot, mijoz va zaxira tahrirlari. Doʻkonni oching va uning {tab} da {button} ni bosing — ikki marta bosish xavfsiz. Shopify quyidagi manzilga yuboradi:',
'Shopify_G_Webhooks_Tab' => 'Webhooklar yorligʻi',
'Shopify_G_Webhooks_Note' => 'Manzil internetdan HTTPS orqali ochiladigan boʻlishi kerak — Shopify {localhost} yoki {test} domeniga yetkazmaydi. Har bir yetkazma bir marta qayd etiladi, shuning uchun Shopify ning qayta urinishlari dublikat buyurtma yarata olmaydi, muvaffaqiyatsiz yetkazmani esa qayta ijro etish mumkin. 1-qadamdagi imzo secret i saqlanmaguncha yetkazmalar rad etiladi.',
'Shopify_G_Instant_Out' => 'Darhol zaxira yuborish — ERP → doʻkon',
'Shopify_G_Setting_Missed' => 'Bu koʻpchilik eʼtibordan chetda qoldiradigan sozlama',
'Shopify_G_Pos_Not_Auto' => 'POS savdosi Shopify ga oʻz-oʻzidan yetib boradigan {not}. Oʻchirilgan boʻlsa, doʻkon bu haqda faqat keyingi Inventar yuborish qadamida biladi — va shu oraliqda kassada allaqachon sotilgan birlikni sotib yuborishi mumkin.',
'Shopify_G_Not' => 'emas',
'Shopify_G_Tick_Push' => '{where} da {setting} belgisini qoʻying. Butun sozlash shu — worker ham, cron ham kerak emas. Shundan soʻng har bir savdo, qaytarish va tuzatish savdo saqlangandan soʻng darhol faqat oʻsha mahsulotlar uchun yuborish amalga oshiradi, yigirma qatorli savdo esa yigirmata emas, bitta yuborishga teng. Kassa uni hech qachon kutmaydi.',
'Shopify_G_This_Store' => 'Bu doʻkon:',
'Shopify_G_Push_On' => 'yoqilgan — zaxira oʻzgarishda yuboriladi',
'Shopify_G_Push_Off' => 'oʻchirilgan — zaxira faqat jadval boʻyicha',
'Shopify_G_Push_Note' => 'Faqat Shopify moslashtirishi allaqachon mavjud boʻlgan mahsulotlar va faqat shu doʻkon omboridagi harakatlar yuboriladi. Ommaviy amallar — mahsulotni oʻchirish, omborni tozalash — zaxirani hodisa chaqirmasdan yozadi, bu rejalashtirilgan inventar qadamini ham saqlashning bir sababi.',
'Shopify_G_Nothing_Install' => 'Boshqa hech narsa oʻrnatish shart emas',
'Shopify_G_No_Worker_Note' => 'Ikkala qismga ham navbat worker i yoki cron yozuvi kerak emas. Kiruvchi webhook Shopify yuborgan soʻrov ichida qayta ishlanadi; chiquvchi zaxira yuborish savdoga xizmat koʻrsatgan jarayonning oʻzida, javob qaytarilgandan {after} ishlaydi — shuning uchun kassa hech qachon Shopify ni kutmaydi, javob bermay qolgan doʻkon esa oʻn soniyadan keyin tark etiladi va keyingi rejalashtirilgan inventar yuborishiga qoldiriladi.',
'Shopify_G_After' => 'keyin',
'Shopify_G_Artisan_Note' => 'Bitta istisno: artisan buyrugʻi orqali qilingan zaxira oʻzgarishida keyin keladigan javob yoʻq, shuning uchun u {queue} navbatiga qoʻyiladi. Ularning ham tezda yuborilishini istasangiz, ushbu navbatni boʻshating:',
'Shopify_G_On_Schedule' => 'Jadval boʻyicha',
'Shopify_G_On_Lower' => 'yoqilgan',
'Shopify_G_Off_Lower' => 'oʻchirilgan',
'Shopify_G_Scheduled_Lead' => 'Hamma narsa vaqti-vaqti bilan ikkala yoʻnalishda qayta tekshiriladi. Real vaqtdan sekinroq, lekin aynan shu darhol yuborishdan foydalanmaydigan doʻkonlarda zaxirani yuboradi, oʻtkazib yuborilgan webhookni ushlaydi va butun katalogni koʻchirishning yagona yoʻlidir.',
'Shopify_G_Cron_Entry' => 'Cron yozuvi',
'Shopify_G_Cron_Entry_Desc' => 'Usiz hech qanday rejalashtirilgan narsa ishlamaydi. Bitta qator, faqat shu modul uchun — uni rejalashtirishni tanlagan boshqa narsalaringiz yoniga qoʻshing:',
'Shopify_G_Cron_Note' => 'Har besh daqiqa — reja foydalana oladigan eng kichik aniqlik, chunki besh daqiqa eng qisqa qadam oraligʻi. Kattaroq oraliq shunchaki pastki chegaraga aylanadi — {example} bilan 5 daqiqaga belgilangan qadam har 15 daqiqada ishlaydi. Windows da Task Scheduler dan foydalaning: dastur {program}, argumentlar {args}, {dir} da ishga tushiriladi.',
'Shopify_G_Switch_On_Plan' => 'Uni yoqing va rejani tanlang',
'Shopify_G_Plan_Desc' => '{where} Kalit cron umuman harakat qila oladimi yoki yoʻqligini belgilaydi; reja esa u nima qilishini belgilaydi. {step} — oʻz oraligʻiga ega bitta yoʻnalishdagi bitta obyekt — {first}, {second}. Standart oraliq oʻz maydonini boʻsh qoldirgan har qanday qadam tomonidan ishlatiladi.',
'Shopify_G_Step_Lower' => 'qadam',
'Shopify_G_Plan_Note' => 'Rejani boʻsh qoldiring va doʻkon standart oraliqda buyurtmalarni tortadi va zaxirani yuboradi — koʻpchilik doʻkonlarga aynan shu kerak. Buyurtmalar faqat tortiladi: Shopify — mijoz buyurtma beradigan joy.',
'Shopify_G_Schedule_On' => 'jadval yoqilgan',
'Shopify_G_Schedule_Off' => 'jadval oʻchirilgan — faqat qoʻlda',
'Shopify_G_When_Step_Runs' => 'Qadam aslida qachon ishlaydi',
'Shopify_G_When_Note' => 'Qadamning muddati, agar xuddi shu qadam oxirgi marta uning oraligʻidan uzoqroq vaqt oldin {started} boʻlsa, keladi; bu ishga tushirishlar tarixidan oʻqiladi. Shunday qilib, qoʻlda boshlagan sinxronlashingiz keyingi avtomatik sinxronlashni kechiktiradi, doimiy muvaffaqiyatsiz boʻlayotgan qadam esa har safar emas, oʻz oraligʻida qayta uriniladi. Doʻkonning Umumiy koʻrinishi har bir qadamning oxirgi ishga tushirilishini, keyingi muddatini va bloklangan boʻlsa, sababini koʻrsatadi. Birinchi katalog yuborishni jadvalga qoʻyishdan oldin qoʻlda — avval {dryRun} bilan — ishga tushiring.',
'Shopify_G_Started_Lower' => 'boshlangan',
'Shopify_G_Where_Setting' => 'Har bir sozlama qayerda joylashgan',
'Shopify_G_Where_Setting_Note' => 'Bularning barchasi mavjud doʻkonda: {path}, soʻngra qalam belgisi (yoki doʻkonning oʻz sahifasidagi {edit}).',
'Shopify_G_Product_Images' => 'Mahsulot rasmlari',
'Shopify_G_Img_1' => 'Rasmlar mahsulot bilan {push} paytida yuboriladi — avval asosiy rasm, soʻngra galereya, soʻngra oʻz rasmi bor har bir variant uchun bittadan, ellikkacha.',
'Shopify_G_Products_Push' => 'mahsulotlarni yuborish',
'Shopify_G_Img_2' => 'Variant rasmi mahsulot bilan yuklanadi va soʻngra {assigned} — Shopify buni shunday modellashtiradi: variant mahsulot rasmlaridan biriga ishora qiladi. Asosiy rasmdan qayta foydalanadigan variant uni ikki marta yuklamaydi.',
'Shopify_G_Assigned' => 'oʻsha variantga biriktiriladi',
'Shopify_G_Img_3' => 'Fayl sifatida saqlangan rasm Shopify ga havola sifatida emas, {uploaded}, shuning uchun bu oʻrnatma internetdan ochilmasa ham ishlaydi. Joylangan havola sifatida qoʻshilgan rasm Shopify ga oʻsha URL sifatida beriladi va u ochiq boʻlishi kerak.',
'Shopify_G_Uploaded' => 'yuklanadi',
'Shopify_G_Img_4' => 'Ular faqat haqiqatan oʻzgarganda qayta yuboriladi — faqat narxni oʻzgartiradigan yuborish doʻkon rasmlariga tegmaydi, chunki ularni yuborish butun toʻplamni almashtiradi.',
'Shopify_G_Img_5' => 'ERP da rasmni oʻchirish uni Shopify da oʻchiradi degani {not}. Uni u yerda ham oʻchiring, aks holda doʻkon uni koʻrsatishda davom etadi.',
'Shopify_G_Commands' => 'Bilish foydali buyruqlar',
'Shopify_G_Command_Copied' => 'Buyruq nusxalandi',
'Shopify_G_Foot' => 'Har bir sinxronlash {logs} ga yoziladi va har bir doʻkonning Umumiy koʻrinishi har bir qadam oxirgi marta qachon bajarilganini, keyingisi qachon kutilayotganini va biror narsa toʻsib qoʻysa, nima toʻsayotganini koʻrsatadi. Sinxronlash kutganingizdek ishlamasa, avvalo shu yerga qarang.',
'Shopify_G_Covers' => 'Qamrab oladi',
'Shopify_G_Covers_Rt' => 'Shopify da qilingan buyurtmalar va tahrirlar; ERP dan chiqayotgan zaxira (POS savdosi, qaytarish, tuzatish)',
'Shopify_G_Covers_Sch' => 'Hammasi, ikki tomonlama — katalog yuborishlari va tezkor yoʻl oʻtkazib yuborgan har qanday narsa bilan birga',
'Shopify_G_Speed' => 'Tezlik',
